Mashup.mashupContent:
{ "CustomMashupCss" : "/* Make selected cards visible when selecting from map */
.BMCollectionViewCellWrapper.BMCollectionViewCellSelected{
 opacity: 1 !important;
}

/* Google map - Cluster toggle button styled like Google Map widget buttons */
.clusterToggleBox .widget-flexcontainer{
	box-shadow: 0px 1px 2px 1px rgba(0,0,0,0.07);
	border-radius: 2px !important;
	height: 40px !important; 
}
/* Google map - Cluster toggle button positioned like Google Map widget buttons */
.overlay .widget-flexcontainer{
 overflow: visible !important; 
}

/*** DARK THEME ***/
/* Collection - Darker shadow under cards */
.DarkTheme .assetCards .BMCollectionViewCellWrapper{ 
	box-shadow: 0px 2px 8px 2px rgba(0,0,0,0.65) !important;
}
/* Collection - Darker shadow on card hover */
.DarkTheme .assetCards .BMCollectionViewCellWrapper:hover{
	box-shadow: 0px 2px 8px 4px rgba(0,0,0,1) !important;
}

/** Fix **/
/* Collection - Prevents card font change on double click in 9.3.0 */
.DarkTheme .assetCardSelectedLabel ptcs-label::part(label), .DarkTheme .assetCardAssetLabel ptcs-label::part(label){
	color: white !important;
 font-size: 14px !important;
 font-weight: 600 !important;
}
