{ "CustomMashupCss" : "/* Reveals shadow on the left side of the cells */
.AssetDetailCollection .BMCollectionViewCellWrapper{
 margin: 0px 0px 0px 1px;
}

/* Collection - Line under menu item */
.AssetDetailMenu .BMCollectionViewCellSelected {
 border-bottom: 2px solid var(--accentColor) !important;
}

/* Collection - Makes collection align to the right */
.AlignRight .BMCollectionViewCellWrapper {
	position: relative !important;
	transform: translate(-24px, 8px) !important;
	float: right !important;
}

/* Background behind displayed data */
.DarkTheme .DataReadingBackground >div {
	background: #111516 !important;
}

/* Button - Card button background on hover */
.DarkTheme .backButton .widget-ptcsbutton:hover, .DarkTheme .backButton .widget-ptcsbutton:focus {
	background: #343C3E !important;
}
/* Button - Card button background on selection */
.DarkTheme .backButton .widget-ptcsbutton:hover:active, .backButton .cardDetailsButton .widget-ptcsbutton:active{
	background: #3D4647 !important;
}





