// the input selectedProperties is an infotable
// convert it to a JSON object (map)
// the key is the property name and the value is the display name,
// if display name is not presented, then using property name as the display name too.
result={};
try{
  if(selectedTrendProperties !== undefined && selectedTrendProperties !== null && selectedTrendProperties.rows){
    let json_value=selectedTrendProperties.ToJSON();
    logger.warn("selectedTrendProperties:"+json_value);

    for(let index=0;index<selectedTrendProperties.rows.length;index++){
      let selectedRow=selectedTrendProperties.rows[index];
      let propertyName=selectedRow["item"];
      let displayName=selectedRow["PropertyDisplayName"];

      result[propertyName]=displayName;
    }
  }

}catch(e){
  logger.error(e);
}

// table: INFOTABLE dataShape: ""
let table = me.GetConfigurationTable({
  tableName: 'DefaultAgentThing' /* STRING */
});

if(table.rows.length>0){
  result=table.rows[0]['defaultAgentThing'];
}
